def _reviewed_fixed_lot_execution_projection(source: str, name: str, expected: str) -> bool:
    """Reinline the exact extracted legacy pipeline; selected route stays separately pinned."""
    if name != "run_certified_strategy_one_session":
        return False
    tree = ast.parse(source)
    functions = [n for n in tree.body if isinstance(n, ast.AsyncFunctionDef) and n.name == name]
    helpers = [n for n in tree.body if isinstance(n, ast.FunctionDef)
               and n.name == "prepare_strategy_one_entry_authorities"]
    if len(functions) != 1 or len(helpers) != 1:
        return False
    function, helper = functions[0], helpers[0]
    if (sha256(ast.unparse(function).encode()).hexdigest() != 'bdc65b58e28c9c7d047acf68d623afe816af0f46dfaeddd09bf14d4b71516cdb'
            or sha256(ast.unparse(helper).encode()).hexdigest() != 'e1e4aa7037c4a222cec56e78df94da62a7f642de9ff42deb8f93760a3523edaf'):
        return False
    class BindInheritedNames(ast.NodeTransformer):
        def visit_Name(self, node):
            if node.id == "strategy_number":
                return ast.parse("runtime.config.strategy_revision").body[0].value
            if node.id == "run_id":
                return ast.parse("runtime.run_id").body[0].value
            return node
    inherited = BindInheritedNames().visit(ast.Module(helper.body[3:-1], [])).body
    price_if = next(n for n in function.body if isinstance(n, ast.If)
                    and ast.unparse(n.test) == "price_authority is not None")
    inherited[-1].body.insert(1, price_if.body[0])
    inherited[-1].body.extend(price_if.body[1:])
    assignments = [i for i,n in enumerate(function.body) if isinstance(n, ast.Assign)
                   and ast.unparse(n.targets[0]) == "selected_session"]
    if len(assignments) != 2:
        return False
    second = assignments[1]
    function.body[second:second + 4] = inherited
    first = assignments[0]
    del function.body[first:first + 2]
    class LegacyRoute(ast.NodeTransformer):
        def visit_BoolOp(self, node):
            node = self.generic_visit(node)
            node.values = [n for n in node.values if ast.unparse(n) != "selected_session is None"]
            return node.values[0] if len(node.values) == 1 else node
        def visit_IfExp(self, node):
            if ast.unparse(node.test) == "selected_session is not None and resume_manager_state is not None":
                return node.orelse
            return self.generic_visit(node)
    function = LegacyRoute().visit(function)
    # The exact current anchor above binds this selected-only count branch.
    count_branches = [(node, field, index) for node in ast.walk(function)
                      for field, value in ast.iter_fields(node) if isinstance(value, list)
                      for index, item in enumerate(value) if isinstance(item, ast.If)
                      and ast.unparse(item.test) == 'manager._fixed_lot_owner is not None']
    if len(count_branches) != 1:
        return False
    node, field, index = count_branches[0]
    del getattr(node, field)[index]
    return sha256(ast.unparse(function).encode()).hexdigest() == expected


