def _reviewed_fixed_lot_ast_recipe(source: str, relative: str, name: str, expected: str) -> bool:
    """Apply only exact reviewed AST edits; complete retained legacy pin remains required."""
    supplied_source = source
    from .backtest_declared_early_risk_compatibility import restore_reviewed_parent_source as restore_early_risk
    source = restore_early_risk(source, relative)
    from .backtest_fixed_structural_lot_compatibility_v9 import restore_reviewed_parent_source as restore_v9
    from .backtest_fixed_structural_lot_compatibility_v10 import restore_reviewed_parent_source as restore_v10
    from .backtest_fixed_structural_lot_compatibility_v11 import restore_reviewed_parent_source as restore_v11
    from .backtest_fixed_structural_lot_compatibility_v12 import restore_reviewed_parent_source as restore_v12
    source = restore_v12(source, relative)
    source = restore_v11(source, relative)
    source = restore_v10(source, relative)
    source = restore_v9(source, relative)
    from .backtest_fixed_structural_lot_compatibility_v8 import restore_reviewed_parent_source as restore_v8
    source = restore_v8(source, relative)
    from .backtest_fixed_structural_lot_compatibility_v7 import restore_reviewed_parent_source as restore_v7
    source = restore_v7(source, relative)
    from .backtest_fixed_structural_lot_compatibility_v6 import restore_reviewed_parent_source as restore_v6
    source = restore_v6(source, relative)
    from .backtest_fixed_structural_lot_compatibility_v5 import restore_reviewed_parent_source as restore_v5
    source = restore_v5(source, relative)
    from .backtest_fixed_structural_lot_compatibility_v4 import restore_reviewed_parent_source as restore_v4
    source = restore_v4(source, relative)
    from .backtest_fixed_structural_lot_compatibility_v3 import restore_reviewed_parent_source
    source = restore_reviewed_parent_source(source, relative)
    from .backtest_fixed_structural_lot_compatibility_v2 import restore_reviewed_parent_source
    source = restore_reviewed_parent_source(source, relative)
    if source != supplied_source:
        restored_tree = ast.parse(source)
        restored_nodes = ([restored_tree] if name == '__module__' else
            [node for node in ast.walk(restored_tree)
             if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef))
             and node.name == name])
        if (len(restored_nodes) == 1
                and sha256(ast.unparse(restored_nodes[0]).encode()).hexdigest() == expected):
            return True
    recipe = _FIXED_LOT_LEGACY_AST_RECIPES.get((relative, name))
    if recipe is None or recipe["legacy_ast"] != expected:
        return False
    tree = ast.parse(source)
    nodes = [tree] if name == "__module__" else [n for n in ast.walk(tree)
        if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)) and n.name == name]
    if len(nodes) != 1 or sha256(ast.unparse(nodes[0]).encode()).hexdigest() != recipe["current_ast"]:
        return False
    def encode(value):
        if value is Ellipsis:
            return {"_literal": "ellipsis"}
        if type(value) is bytes:
            return {"_bytes": value.hex()}
        if isinstance(value, ast.AST):
            return {"_ast": type(value).__name__, "fields": {k: encode(v) for k, v in ast.iter_fields(value)}}
        return [encode(v) for v in value] if isinstance(value, list) else value
    def decode(value):
        if isinstance(value, dict):
            if value == {"_literal": "ellipsis"}:
                return Ellipsis
            if set(value) == {"_bytes"} and type(value["_bytes"]) is str:
                return bytes.fromhex(value["_bytes"])
            if set(value) == {"_statement"}:
                statements = ast.parse(value["_statement"]).body
                if len(statements) != 1:
                    raise ValueError("Exact one recipe statement required")
                return statements[0]
            kind = getattr(ast, value.get("_ast", ""), None)
            if not isinstance(kind, type) or not issubclass(kind, ast.AST) or set(value) != {"_ast", "fields"}:
                raise ValueError("Closed AST recipe node required")
            if set(value["fields"]) != set(kind._fields):
                raise ValueError("Closed AST recipe fields differ")
            return kind(**{k: decode(v) for k, v in value["fields"].items()})
        return [decode(v) for v in value] if isinstance(value, list) else value
    def fragment_hash(value):
        return sha256(json.dumps(encode(value), sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    root = nodes[0]
    seen = set()
    if not 0 < len(recipe["edits"]) <= 512:
        return False
    for edit in recipe["edits"]:
        if (type(edit) is not dict or type(edit.get("path")) is not list
                or any(type(step) not in (str, int) or type(step) is int and step < 0 for step in edit["path"])
                or type(edit.get("current_hash")) is not str or len(edit["current_hash"]) != 64
                or edit.get("op") not in {"replace", "splice"}
                or set(edit) != ({"path", "op", "current_hash", "replacement", "start", "count"}
                                if edit.get("op") == "splice" else {"path", "op", "current_hash", "replacement"})):
            return False
        if edit["op"] == "splice" and (type(edit["start"]) is not int or type(edit["count"]) is not int
                or edit["start"] < 0 or edit["count"] < 0):
            return False
        identity = (tuple(edit["path"]), edit["op"], edit.get("start"))
        if identity in seen:
            return False
        seen.add(identity)
        target = root
        try:
            if edit["op"] == "splice":
                for step in edit["path"]:
                    target = target[step] if type(step) is int else getattr(target, step)
                start, count = edit["start"], edit["count"]
                if type(target) is not list or not 0 <= start <= start + count <= len(target):
                    return False
                if fragment_hash(target[start:start + count]) != edit["current_hash"]:
                    return False
                target[start:start + count] = decode(edit["replacement"])
            elif edit["op"] == "replace" and edit["path"]:
                for step in edit["path"][:-1]:
                    target = target[step] if type(step) is int else getattr(target, step)
                last = edit["path"][-1]
                value = target[last] if type(last) is int else getattr(target, last)
                if fragment_hash(value) != edit["current_hash"]:
                    return False
                replacement = decode(edit["replacement"])
                if type(last) is int:
                    target[last] = replacement
                else:
                    setattr(target, last, replacement)
            else:
                return False
        except (AttributeError, IndexError, KeyError, TypeError, ValueError):
            return False
    return sha256(ast.unparse(ast.fix_missing_locations(root)).encode()).hexdigest() == expected


